package app.truemotion.vector;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.net.Uri;
import java.io.*;
import java.lang.ref.WeakReference;

/** Imports packaged XFL/modern FLA through the standard document picker. */
public final class VectorFileActivity extends Activity {
    static WeakReference<VectorEditor> pending=new WeakReference<VectorEditor>(null);
    public static final int FLA=0,SVG=1,ATLAS=2,EXPORT=3,PSD=4,PHOTO=5,VIDEO=6,AUDIO=7;int mode;byte[] atlasXml;
    public static void open(VectorEditor editor){open(editor,FLA);}
    public static void open(VectorEditor editor,int mode){editor.stop();editor.stage.finishPen();pending=new WeakReference<VectorEditor>(editor);editor.activity.startActivity(new Intent(editor.activity,VectorFileActivity.class).putExtra("mode",mode));}
    static String warnings(VectorXfl.Result result){StringBuilder text=new StringBuilder();for(String warning:result.warnings){if(text.length()>0)text.append('\n');if(warning.equals("Text fonts and layout require visual checking"))text.append(L10n.t("Проверьте шрифты и расположение текста"));else if(warning.equals("Unsupported artwork: DOMBitmapInstance"))text.append(L10n.t("Растровые изображения FLA пока не импортируются"));else if(warning.equals("Layer type: mask"))text.append(L10n.t("Маски FLA требуют ручной настройки"));else if(warning.equals("An open fill contour requires manual checking"))text.append(L10n.t("Проверьте незамкнутые контуры заливки"));else if(warning.equals("A tween needs manual topology matching"))text.append(L10n.t("Для твина требуется сопоставить узлы объектов"));else if(warning.equals("ActionScript retained as disabled source; execution is not supported"))text.append(L10n.t("ActionScript сохранён как текст и отключён. Используйте JavaScript для новых сценариев."));else if(warning.equals("Sheared symbol/text transform requires manual checking"))text.append(L10n.t("Проверьте наклон символов и текста"));else text.append(warning);}return text.toString();}
    @Override public void onCreate(Bundle state){super.onCreate(state);L10n.use(this);mode=getIntent().getIntExtra("mode",FLA);if(state==null){Intent picker;if(mode==EXPORT)picker=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").putExtra(Intent.EXTRA_TITLE,VectorSprites.pending.name+"-sprites.zip");else picker=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(mode==PHOTO?"image/*":mode==VIDEO?"video/*":mode==AUDIO?"audio/*":"*/*");picker.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(picker,7);}else if(pending.get()==null)finish();}
    byte[] bytes(Uri uri,int limit)throws Exception{try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException(L10n.t("Не удалось открыть документ"));ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] block=new byte[16384];int count;while((count=input.read(block))>=0){if(count==0)continue;if((long)output.size()+count>limit)throw new IOException(L10n.t("Слишком большой файл импорта"));WorkBudget.memory(((long)output.size()+count)*4);output.write(block,0,count);}return output.toByteArray();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){finish();return;}final Uri uri=data.getData();final VectorEditor editor=pending.get();if(editor==null){finish();return;}ProgressDialog progress=new ProgressDialog(this);progress.setMessage(L10n.t("Обработка документа…"));progress.setCancelable(false);progress.show();new Thread(()->{try{
        if(mode==EXPORT){VectorDocument copy=VectorDocument.read(editor.doc.json());VectorSprites.write(this,uri,copy,VectorSprites.pending);runOnUiThread(()->{progress.dismiss();finish();android.widget.Toast.makeText(editor.activity,L10n.t("Спрайты PNG + XML сохранены"),1).show();});return;}
        if(mode==ATLAS&&request==7){byte[] source=bytes(uri,64*1024*1024);if(source.length>2&&source[0]=='P'&&source[1]=='K'){VectorDocument imported=atlasZip(source,editor.doc.fps);complete(progress,editor,imported,new java.util.LinkedHashSet<String>(),false);return;}VectorAtlas.read(source);atlasXml=source;runOnUiThread(()->{progress.dismiss();android.widget.Toast.makeText(this,L10n.t("Выберите PNG, указанный в XML-атласе"),1).show();startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/png").addCategory(Intent.CATEGORY_OPENABLE),8);});return;}
        if(mode==ATLAS){VectorImage image=VectorRaster.image(bytes(uri,64*1024*1024));VectorDocument imported=VectorAtlas.read(atlasXml).document(image,editor.doc.fps);complete(progress,editor,imported,new java.util.LinkedHashSet<String>(),false);return;}
        if(mode==PSD){PsdFile psd=PsdFile.read(bytes(uri,128*1024*1024));complete(progress,editor,PsdRaster.document(psd,editor.doc.fps,editor.doc.frames),psd.warnings,false);return;}
        if(mode>=PHOTO){VectorMedia.importFile(this,editor,uri,mode,()->{progress.dismiss();finish();});return;}
        VectorXfl.Result imported;try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException(L10n.t("Не удалось открыть документ"));imported=mode==SVG?VectorSvg.read(input):VectorXfl.read(input);}complete(progress,editor,imported.document,imported.warnings,mode==FLA);
    }catch(Exception error){runOnUiThread(()->{progress.dismiss();finish();editor.handler.postDelayed(()->editor.error(error),250);});}},"TrueVectorDocument").start();}
    void complete(ProgressDialog progress,VectorEditor editor,VectorDocument imported,java.util.LinkedHashSet<String> warnings,boolean replace){runOnUiThread(()->{progress.dismiss();finish();editor.handler.postDelayed(()->{Runnable apply=()->{editor.snapshot();editor.playbackPose=null;if(replace){editor.doc=imported;editor.frame=editor.track=0;editor.stage.fit();}else if(mode==PSD){double dx=(editor.doc.width-imported.width)/2d,dy=(editor.doc.height-imported.height)/2d;editor.doc.images.putAll(imported.images);for(VectorDocument.Track t:imported.tracks){for(VectorDocument.Cel c:t.keys.values())for(VectorDocument.Shape s:c.shapes){s.x+=dx;s.y+=dy;}editor.doc.tracks.add(t);}editor.track=editor.doc.tracks.size()-1;}else{VectorSymbol symbol=new VectorSymbol(mode==SVG?L10n.t("SVG рисунок"):L10n.t("Спрайты"),imported);editor.doc.images.putAll(imported.images);for(VectorSymbol asset:imported.symbols.values())editor.doc.symbols.put(asset.id,asset);editor.doc.symbols.put(symbol.id,symbol);for(VectorSymbol asset:editor.doc.symbols.values()){asset.document.symbols=editor.doc.symbols;asset.document.images=editor.doc.images;}VectorDocument.Shape shape=new VectorDocument.Shape();shape.symbol=symbol.id;shape.name=symbol.name;shape.x=editor.doc.width/2d;shape.y=editor.doc.height/2d;shape.symbolStart=editor.doc.time(editor.frame);double scale=Math.min(1,Math.min(editor.doc.width/(double)imported.width,editor.doc.height/(double)imported.height));shape.sx=shape.sy=scale;editor.edit().shapes.add(shape);}editor.selected.clear();editor.stage.renderer.clear();editor.refresh();};if(warnings.isEmpty())apply.run();else {VectorXfl.Result result=new VectorXfl.Result();result.warnings.addAll(warnings);new AlertDialog.Builder(editor.activity).setTitle(L10n.t("Проверьте импорт")).setMessage(L10n.t("Некоторые функции требуют ручной проверки или не поддерживаются:")+"\n\n"+warnings(result)).setPositiveButton(L10n.t("Импортировать поддержанное"),(d,n)->apply.run()).setNegativeButton(L10n.t("Отмена"),null).show();}},250);});}
    VectorDocument atlasZip(byte[] source,double fps)throws Exception{java.util.Map<String,byte[]> files=new java.util.LinkedHashMap<String,byte[]>();long total=0;try(java.util.zip.ZipInputStream zip=new java.util.zip.ZipInputStream(new ByteArrayInputStream(source))){java.util.zip.ZipEntry entry;while((entry=zip.getNextEntry())!=null){String name=entry.getName().replace('\\','/');if(entry.isDirectory()||!(name.endsWith(".png")||name.endsWith(".xml")))continue;ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[16384];int count;while((count=zip.read(block))>=0){if(count==0)continue;total+=count;WorkBudget.memory(total*4);if(total>128*1024*1024)throw new IOException(L10n.t("Слишком большой файл импорта"));out.write(block,0,count);}if(files.put(name,out.toByteArray())!=null)throw new IOException("Duplicate atlas entry");}}
        VectorDocument combined=new VectorDocument(1,1,fps,1);combined.tracks.get(0).keys.clear();int frame=0;for(java.util.Map.Entry<String,byte[]> entry:files.entrySet())if(entry.getKey().endsWith(".xml")){VectorAtlas atlas=VectorAtlas.read(entry.getValue());String name=entry.getKey(),prefix=name.contains("/")?name.substring(0,name.lastIndexOf('/')+1):"";byte[] png=files.get(prefix+atlas.imagePath);if(png==null)png=files.get(atlas.imagePath);if(png==null)throw new IOException(L10n.t("В архиве отсутствует PNG-атлас"));VectorImage image=VectorRaster.image(png);VectorDocument page=atlas.document(image,fps);combined.images.put(image.id,image);combined.width=Math.max(combined.width,page.width);combined.height=Math.max(combined.height,page.height);combined.fps=page.fps;for(VectorDocument.Cel cel:page.tracks.get(0).keys.values())combined.tracks.get(0).keys.put(frame++,cel);}if(frame==0)throw new IOException("No TextureAtlas XML");combined.frames=frame;for(VectorDocument.Cel cel:combined.tracks.get(0).keys.values())for(VectorDocument.Shape shape:cel.shapes){shape.x=combined.width/2d;shape.y=combined.height/2d;}combined.validate();return combined;
    }
}
